import { panelList, panelsChosen, panelsReady, panelState, productPreviewStatus } from './panels.js';
import { approvalBlocker } from './approval.js';

export function productCompletion(p,{esc,safeImage,icon=()=>'',busy=false}){
  busy=busy||['running','queued'].includes(p.aiJob?.status);
  const status=productPreviewStatus(p),chosen=panelsChosen(p),current=['current','legacy'].includes(status),hasImage=Boolean(p.assets?.preview);
  const count=panelList(p).filter(x=>panelState(x)==='selected').length,blocker=approvalBlocker(p);
  const title=p.approved&&current?'Виріб прийнято':!chosen?'Оберіть усі панелі':status==='missing'?'Створіть загальний вигляд':status==='outdated'?'Загальний вигляд потребує оновлення':'Перегляньте готовий виріб';
  return `<section class="panel-workspace product-completion" aria-label="Завершення виробу"><div class="panel-step-heading"><h3>${title}</h3><span class="badge ${current?'green':''}">${status==='missing'?'Ще не створено':status==='outdated'?'Потребує оновлення':status==='legacy'?'Збережений вигляд':'Актуальний вигляд'}</span></div><p>Обрано панелей: ${count} із ${panelList(p).length}. Загальний вигляд створюється за готовим декором усіх панелей.</p>${!chosen?'<p class="hint">Відкрийте необрані панелі у списку та підтвердьте потрібні зображення.</p>':''}${hasImage?`<div class="viewer"><div class="viewer-toolbar"><strong>Загальний вигляд виробу</strong><button class="iconbtn" data-action="expand" aria-label="Відкрити зображення">${icon('expand')}</button></div><div class="canvas"><img src="${safeImage(p.assets.preview)}" alt="Загальний вигляд — ${esc(p.title)}"></div></div>`:'<div class="completion-placeholder"><p>Після вибору панелей можна побачити виріб у зборі.</p></div>'}${status==='outdated'?'<p class="note">Показано попередній загальний вигляд. Створіть новий за поточними обраними панелями.</p>':''}${status==='current'?'<p class="hint">Вигляд прив’язаний до поточної версії панелей. Відповідність перенесеного декору можна перевірити окремо.</p>':''}${status==='legacy'?'<p class="hint">Для цього збереженого зображення немає запису вихідних панелей. Перегляньте відповідність декору перед прийняттям.</p>':''}<div class="actions-wrap completion-main-actions">${!current?`<button class="btn primary" data-action="ai-preview" ${busy||!chosen?'disabled':''}>${hasImage?'Оновити':'Згенерувати'} загальний вигляд</button>`:`<button class="btn primary" data-action="approve" ${busy||blocker||p.approved?'disabled':''}>${p.approved?'Виріб прийнято':'Прийняти виріб'}</button><button class="btn" data-action="ai-preview" ${busy||!chosen?'disabled':''}>Інший загальний вигляд</button>`}</div>${current&&blocker?`<p class="hint">${esc(blocker)}</p>`:''}<p class="hint">Перевірка ШІ та контури запускаються окремими кнопками. Рішення про прийняття виробу залишається за вами.</p><div class="completion-checks"><h3>Перевірка та контури комплекту</h3><div class="actions-wrap"><button class="btn" data-action="ai-review" ${busy||!current?'disabled':''}>Перевірити весь комплект</button><button class="btn" data-action="ai-trace-all" ${busy||!panelsReady(p)?'disabled':''}>Створити контури всіх панелей</button></div><p class="hint">Перевірка порівнює панелі із загальним виглядом. Контури створюються для кожної панелі за її кольоровим декором.</p></div></section>`;
}
